/* The Better Auth sign-in screen (web + desktop entry, ADR-0024) is a single card, so it sizes and
   aligns itself instead of inheriting the .pageIndexIndex composition or the centered, bare-field
   defaults of .pageAuth above. */
.pageAuthBetterLogin .frame {
  width: 424px;
  padding: 48px;
  text-align: left;
}
.pageAuthBetterLogin .intro {
  display: flex;
  flex-direction: column;
  gap: 2px 0px;
  margin: 0px 0px 32px 0px;
}
.pageAuthBetterLogin .intro .label {
  margin: 0px;
}
.pageAuthBetterLogin .intro .label.line1 {
  font-size: var(--font-size-header1);
  line-height: var(--line-height-header1);
  letter-spacing: var(--letter-spacing-header1);
  font-weight: var(--font-weight-header1);
  font-weight: 600;
  color: var(--color-text-primary);
}
.pageAuthBetterLogin .intro .label.line2 {
  font-size: var(--font-size-paragraph);
  line-height: var(--line-height-paragraph);
  letter-spacing: var(--letter-spacing-paragraph);
  color: var(--color-text-secondary);
}
.pageAuthBetterLogin .buttons {
  margin: 24px 0px 0px 0px;
}
.pageAuthBetterLogin .button {
  width: 100%;
}
@media (max-width: 464px) {
  .pageAuthBetterLogin .frame {
    width: calc(100% - 32px);
    padding: 32px 24px;
  }
}

.pageAuthBetterLogin .field {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px 0px;
  margin: 0px 0px 16px 0px;
}
.pageAuthBetterLogin .field {
  /* `.pageAuth .input` is written for a bare field (40px tall, centered text) - here the input
     sits under its own label, so both of those fall away and the box is ours to set */
}
.pageAuthBetterLogin .field .label {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
  font-weight: 500;
  margin: 0px;
  padding-left: 2px;
  color: var(--color-text-secondary) !important;
}
.pageAuthBetterLogin .field .input {
  width: 100%;
  height: 48px;
  padding: 0px 16px;
  text-align: left;
  border-radius: 12px;
  border: 1px solid var(--color-shape-secondary);
}
.pageAuthBetterLogin .field .input:hover {
  border-color: var(--color-shape-primary);
}
.pageAuthBetterLogin .field .input.isFocused, .pageAuthBetterLogin .field .input:focus {
  border-color: var(--color-system-accent-100);
  box-shadow: 0px 0px 0px 1px var(--color-system-accent-100) inset;
}
.pageAuthBetterLogin .error {
  margin: 0px 0px 4px 0px;
  text-align: left;
}

