  align-items: center;
  min-height: 22px;
}
.pageMainDate .dayName div {
  display: flex;
  flex-direction: row;
  gap: 8px;
  align-items: center;
}
.pageMainDate .dayName div::after {
  content: "";
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--color-control-active);
}
.pageMainDate .dayName div:last-child::after {
  display: none;
}
.pageMainDate .headSimple {
