  height: 20px;
  margin: 0px 6px 0px 0px;
}
.pageMainDate .cell.c-type .iconObject {
  display: none;
}
.pageMainDate .emptyContainer, .pageMainDate #loader {
  text-align: center;
  align-content: center;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: var(--color-text-secondary);
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
