}
.settingsPageContainer .label.small {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
}
.settingsPageContainer .label.section {
  font-size: var(--font-size-paragraph);
  line-height: var(--line-height-paragraph);
  letter-spacing: var(--letter-spacing-paragraph);
  font-weight: 600;
  margin: 0px;
  padding: 8px 0px;
}
.settingsPageContainer .label.red {
  color: var(--color-red);
}
.settingsPageContainer .name {
  width: 100%;
}
.settingsPageContainer .name .label {
  margin: 0px 0px 6px 0px;
}
.settingsPageContainer .name .input {
  font-size: var(--font-size-header2);
  line-height: var(--line-height-header2);
  letter-spacing: var(--letter-spacing-header2);
  font-weight: var(--font-weight-header2);
  padding: 0px;
}
.settingsPageContainer .iconWrapper {
  position: relative;
}
.settingsPageContainer .iconWrapper .loaderWrapper {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  z-index: 1;
  background: var(--color-bg-loader);
}
.settingsPageContainer .iconWrapper .iconObject.canEdit::after {
  content: "";
  position: absolute;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  background: url("~img/icon/camera.svg") no-repeat center;
  background-size: 40px 30px;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  opacity: 0;
  background-color: rgba(0, 0, 0, 0.1);
}
.settingsPageContainer .iconWrapper .iconObject.canEdit:hover:after {
  opacity: 1;
}
.settingsPageContainer .iconWrapper .iconObject.isHuman.canEdit::after {
  border-radius: 50%;
}
.settingsPageContainer .icon.logo {
  width: 54px;
  height: 54px;
  margin: 0px 0px 16px 0px;
}
.settingsPageContainer ol, .settingsPageContainer ul {
  padding-left: 1.35em;
  margin: 8px 0px;
