/* live typing indicator (pubsub presence, see Lib/presence), shared by chats and discussions */
.typingIndicator {
  display: flex;
  align-items: center;
  gap: 0px 6px;
  height: 24px;
  padding: 0px;
  flex-shrink: 0;
  font-size: 12px;
  line-height: 24px;
  color: var(--color-text-secondary);
  animation: chatTypingIn 0.15s ease-out;
}

.typingIndicator .icons {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.typingIndicator .icons .iconObject {
  margin-left: -4px;
  border: 2px solid var(--color-bg-primary);
  border-radius: 50%;
  box-sizing: content-box;
}
.typingIndicator .icons .iconObject:first-child {
  margin-left: -2px;
}
.typingIndicator .label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.typingIndicator .dots {
  display: flex;
  gap: 2px;
  align-items: center;
}
.typingIndicator .dots span {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--color-text-secondary);
  animation: blockPresenceDot 1.2s infinite ease-in-out;
}
.typingIndicator .dots span:nth-child(2) {
  animation-delay: 0.2s;
}
.typingIndicator .dots span:nth-child(3) {
  animation-delay: 0.4s;
}

.block.blockChat .typingIndicator {
  width: 100%;
  max-width: 960px;
  margin: 0px auto 4px auto;
}

@keyframes chatTypingIn {
  from {
    opacity: 0;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
