}

.input.size28 {
  height: 28px;
  border-radius: 14px;
}

.input.size36 {
  height: 36px;
  border-radius: 18px;
}

.input.size40 {
  height: 40px;
  border-radius: 20px;
  padding: 0px 16px;
}

.input.size52 {
  height: 52px;
  border-radius: 26px;
  padding: 0px 16px;
}

.input.size56 {
  height: 56px;
  border-radius: 28px;
  padding: 0px 16px;
}

.input.isReadonly {
