}

.input.isReadonly:hover, .input.isReadonly:focus {
  background: var(--color-shape-highlight-light-solid);
}

.input::placeholder {
  color: var(--color-text-tertiary);
}

/* Use CSS text-security instead of type="password" to avoid macOS SecureEventInput blocking third-party input methods */
