/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.inputWithFile {
  padding: 11px 13px;
  border-radius: 8px;
  border: solid 1px var(--color-shape-secondary);
  color: var(--color-control-active);
  font-size: var(--font-size-common);
  line-height: var(--line-height-common);
  letter-spacing: var(--letter-spacing-common);
  transition: border 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  overflow: hidden;
  line-height: 20px;
  text-align: left;
  display: flex;
  align-items: flex-start;
  gap: 0px 6px;
  white-space: nowrap;
}

.inputWithFile:hover {
  border-color: var(--color-shape-primary);
}

.inputWithFile .inputWithFile-inner {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  flex-grow: 1;
}
.inputWithFile .fileWrap {
  display: inline-block;
  vertical-align: top;
}
.inputWithFile .fileWrap .border {
  border-bottom: 0.05em solid var(--color-control-active);
  display: inline-block;
  line-height: 1;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
}
.inputWithFile .fileWrap:hover .border {
  color: var(--color-text-primary);
}
.inputWithFile .input-text {
  height: 20px;
  line-height: 20px;
  vertical-align: top;
  padding: 0px;
  border: 0px;
  background: none;
  border-radius: 0px;
  color: var(--color-text-primary);
}
.inputWithFile .input::placeholder {
  color: var(--color-control-active);
}
.inputWithFile .urlToggle {
  cursor: text;
  display: inline-block;
}
.inputWithFile .form {
  display: inline-block;
  vertical-align: top;
}
.inputWithFile .icon {
  width: 20px;
  height: 20px;
  transition: none;
}

.inputWithFile.isReadonly .urlToggle {
  cursor: default;
}
.inputWithFile.isReadonly .border {
  border: 0px;
  cursor: default;
}
.inputWithFile.isReadonly .fileWrap:hover .border {
  color: var(--color-control-active);
}

.inputWithFile.isSmall .fileWrap {
  display: block;
}
.inputWithFile.isSmall .txt {
  height: 38px;
}

.inputWithFile.noFile .urlToggle {
  width: 100%;
}
.inputWithFile.noFile .form {
  width: 100%;
}

.inputWithFile.noFile.isSmall .txt {
  height: 20px;
}

.inputWithFile.isFocused .fileWrap {
  display: none;
}
.inputWithFile.isFocused .form {
  width: 100%;
}

.inputWithFile.isSmall.isFocused .txt {
  display: inline-block;
}
.inputWithFile.isSmall.isFocused .fileWrap {
  display: block;
}

.inputWithFile.isIcon .inputWithFile-inner {
  display: none;
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.inputWithLabel {
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--color-shape-secondary);
  cursor: text;
}

.inputWithLabel .inner {
  position: relative;
  width: 100%;
  height: 38px;
  display: block;
}
.inputWithLabel .label {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
  color: var(--color-text-secondary);
}
.inputWithLabel .input {
  padding: 0px !important;
  height: 22px;
  line-height: 22px;
  vertical-align: top;
  border: 0px !important;
  background: none;
  border-radius: 0px;
}

.inputWithLabel:hover {
  border-color: var(--color-shape-primary);
}

.inputWithLabel.isFocused, .inputWithLabel.isFocused:hover {
  padding: 7px 11px;
  border: 2px solid var(--color-system-accent-100);
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.phraseWrapper {
  border-radius: 24px;
  width: 100%;
  position: relative;
  padding: 23px 48px;
  font-size: var(--font-size-header3);
  line-height: 38px;
  text-align: center;
  letter-spacing: -0.12px;
}

.phraseWrapper .phraseInnerWrapper {
  word-break: break-word;
  min-height: 38px;
  position: relative;
  z-index: 1;
}
.phraseWrapper .word {
  font-size: var(--font-size-header3);
  line-height: 18px;
  height: 18px;
  user-select: text !important;
  display: inline;
  margin: 10px;
  vertical-align: middle;
  white-space: nowrap;
  text-transform: lowercase;
}
.phraseWrapper .word:empty {
  margin: 0px;
}
.phraseWrapper .placeholder {
  color: var(--color-text-tertiary);
  top: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
}
.phraseWrapper #entry {
  display: inline;
  font-size: var(--font-size-header3);
  line-height: 18px;
  height: 18px;
  -webkit-user-modify: read-write-plaintext-only;
  user-select: text;
  vertical-align: middle;
  margin-left: 10px;
  text-transform: lowercase;
}
.phraseWrapper .icon {
  height: 20px;
  width: 20px;
  vertical-align: top;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  position: absolute;
  top: 50%;
  cursor: default;
}
.phraseWrapper .icon.hasSvg {
  right: 16px;
  margin: -10px 0px 0px 0px;
}
.phraseWrapper .icon.hasSvg:hover {
  color: var(--color-text-primary);
}
.phraseWrapper .icon.copy {
  right: -32px;
  margin: -14px 0px 0px 0px;
  display: none;
}
.phraseWrapper.isHidden .word {
  border-radius: 8px;
  filter: blur(10px);
  background-color: var(--color-text-primary);
}
.phraseWrapper.isReadonly #entry {
  display: none;
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.pin {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0px 8px;
}

.pin .input {
  width: 40px;
  height: 40px;
  padding: 0px;
  text-align: center;
  vertical-align: top;
  font-size: var(--font-size-header3);
