/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.select {
  border-radius: 4px;
  border: solid 1px var(--color-shape-primary);
  display: inline-block;
  vertical-align: middle;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  font-family: "Inter";
  white-space: nowrap;
  padding: 3px 20px 3px 6px;
  line-height: 20px !important;
}

.select:hover, .select.hover, .select.isFocused {
  background: var(--color-shape-tertiary);
}

.select .icon {
  transition: none;
}
.select:not(.round) .icon.arrow {
  margin: -10px 0px 0px 0px !important;
  right: 0px !important;
  width: 20px !important;
  height: 20px !important;
  position: absolute !important;
  top: 50%;
}
.select .item {
  display: flex;
  background: none !important;
  padding: 0px !important;
  overflow: hidden;
}
.select .item .icon {
  width: 20px;
  height: 20px;
}
.select .item .icon, .select .item .iconObject {
  transition: none;
  margin-right: 6px;
}
.select .item .name {
  width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.select .item .caption, .select .item .note {
  display: none;
}
.select .item::before {
  display: none;
}
.select .currentSelected {
  display: flex;
  align-items: center;
  gap: 0px 6px;
}
.select .clickable {
  display: flex;
  width: 100%;
}

.select.big {
  padding: 9px 26px 9px 12px;
  border-radius: 10px;
}

.select.big .icon.arrow {
  right: 4px !important;
}
.select.big .item .name {
  line-height: 22px;
  font-weight: 600;
}

.select.round {
  display: flex;
  align-items: center;
  gap: 0px 6px;
  border-radius: 14px;
  border: 0px;
  background: var(--color-shape-highlight-light-solid);
  padding: 6px 10px;
}

.select.round.hover, .select.round:hover {
  background: var(--color-shape-highlight-medium);
}
.select.round.size36 {
  height: 36px;
  border-radius: 12px;
}
.select.round .icon.arrow {
  width: 8px;
  height: 8px;
}

.select.isReadonly {
  cursor: default;
  padding-right: 6px;
}

.select.isReadonly .icon.arrow {
  display: none;
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.switch {
  width: 26px;
  height: 16px;
  background: var(--color-shape-secondary);
  border-radius: 16px;
  position: relative;
  display: inline-block;
  vertical-align: middle;
}

.switch .inner {
  width: 12px;
  height: 12px;
  border-radius: 100%;
  background: var(--color-bg-primary);
  position: absolute;
  left: 2px;
  top: 2px;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  box-shadow: 0px 0px 0px 0.5px rgba(0, 0, 0, 0.1);
}
.switch.big {
  width: 40px;
  height: 24px;
  border-radius: 24px;
}
.switch.big .inner {
  width: 20px;
  height: 20px;
}
.switch.isReadonly {
  opacity: 0.4;
}
.switch.active {
  background: var(--color-text-secondary);
}
.switch.active .inner {
  left: auto;
  right: 2px;
}
.switch.active.grey {
  background: var(--color-control-active);
}
.switch.active.yellow {
  background: var(--color-yellow);
}
.switch.active.orange {
  background: var(--color-orange);
}
.switch.active.red {
  background: var(--color-red);
}
.switch.active.pink {
  background: var(--color-pink);
}
.switch.active.purple {
  background: var(--color-purple);
}
.switch.active.blue {
  background: var(--color-system-accent-50);
}
.switch.active.ice {
  background: var(--color-ice);
}
.switch.active.teal {
  background: var(--color-teal);
}
.switch.active.lime {
  background: var(--color-lime);
}

/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
