  border-radius: 6px;
}

.tabSwitch .option {
  position: relative;
  z-index: 1;
  flex: 1 1 0;
  text-align: center;
}
.tabSwitch .highlight {
  position: absolute;
  z-index: 0;
  top: 0px;
  height: 100%;
  border-radius: inherit;
  transition: left 0.2s cubic-bezier(0.22, 1, 0.36, 1);
