/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.popups .popup {
  position: fixed;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  z-index: 101;
}
.popups .popup.show .innerWrap {
  opacity: 1;
  transform: none;
}
.popups .popup.show .dimmer {
  opacity: 1;
}
.popups .popup.showDimmer .dimmer {
  background: rgba(0, 0, 0, 0.25);
}
.popups .popup * {
  user-select: none;
}
.popups .popup .innerWrap {
  position: absolute;
  left: 0px;
  top: 50%;
  z-index: 1;
  background: var(--color-bg-primary);
  border-radius: 24px;
  box-shadow: 0px 2px 28px rgba(0, 0, 0, 0.2);
  opacity: 0;
  transform: scale(0.95, 0.95);
  transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.2s cubic-bezier(0.22, 1, 0.36, 1);
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: none;
}
.popups .popup .dimmer {
  position: absolute;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  z-index: 0;
  transition: opacity 0.2s cubic-bezier(0.22, 1, 0.36, 1);
  opacity: 0;
}
.popups .popup .dimmer {
  /* Dimmer with Graph styles for AI onboarding */
}
.popups .popup .dimmer.withGraph .graphOverlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: auto;
  z-index: 1;
}
.popups .popup .dimmer.withGraph .popupBlocker {
  position: absolute;
  top: calc(50% - 340px);
  left: calc(50% - 360px);
  width: 720px;
  height: 680px;
  pointer-events: auto;
  z-index: 2;
}
.popups .popup .dimmer.withGraph .onboardingGraphWorkerContainer {
  position: absolute;
  top: 0px;
  left: 0px;
  pointer-events: auto;
  opacity: 1;
  z-index: 0;
}
.popups .popup .dimmer.withGraph .onboardingGraphWorkerContainer canvas {
  position: absolute;
  top: 0;
  left: 0;
  cursor: default;
  image-rendering: auto;
  backface-visibility: hidden;
}
.popups .popup #loader {
  position: absolute;
  left: 0px;
  top: 0px;
  z-index: 20;
  width: 100%;
  height: 100%;
  border-radius: 24px;
  background: var(--color-bg-loader);
}

