/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.statusMessage {
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-primary);
  position: relative;
  overflow: hidden;
}
.statusMessage.active .statusText {
  background: linear-gradient(90deg, var(--color-text-primary) 0%, #9B8ADB 25%, #9B8ADB 35%, var(--color-text-primary) 60%, var(--color-text-primary) 100%);
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: waveAnimation 2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}
.statusMessage .statusText {
  display: inline-block;
  transition: all 0.3s ease;
  font-weight: 600;
}

@keyframes waveAnimation {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
