/* Start-up loader: the bubble sits where the sign-in screen's does, this far above the viewport
   centre (mirrored in src/html/index.html for the pre-React bubble); title and status keep the
   gap below from its edge */
.notifications {
  position: fixed;
  right: 12px;
  bottom: 12px;
  z-index: 200;
  width: 384px;
  display: flex;
  flex-direction: column;
}

.notifications .head {
  display: none;
  flex-direction: row;
  justify-content: flex-end;
  align-items: center;
  margin: 0px 0px 14px 0px;
  gap: 0px 8px;
  flex-shrink: 0;
}
.notifications .head .icon {
  width: 24px !important;
  height: 24px !important;
  border-radius: 50%;
  background-color: var(--color-bg-primary);
  border: 1px solid var(--color-shape-secondary);
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
}
.notifications .head .icon:hover {
  background-color: var(--color-shape-highlight-light);
}
.notifications .head .icon.hide {
  background-size: 12px 8px;
}
.notifications .head .icon.clear {
  background-size: 10px;
}
.notifications .body {
  flex-grow: 1;
  position: relative;
}
.notifications .notification {
  width: 100%;
  min-height: 70px;
  background: var(--color-bg-primary);
  border-radius: 12px;
  border: 1px solid var(--color-shape-secondary);
  position: absolute;
  bottom: 0px;
  padding: 16px;
  transform-origin: 50% 0%;
  transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  transition-duration: 0.2s;
  transition-property: transform, opacity, bottom;
  opacity: 1;
  user-select: none;
  box-shadow: 0px 2px 16px 0px rgba(0, 0, 0, 0.07);
}
.notifications .notification.from, .notifications .notification.to {
  opacity: 0;
  transform-origin: 50% 50%;
  transform: scale3d(0.75, 0.75, 1);
}
.notifications .notification .icon.notificationDelete {
  width: 24px !important;
  height: 24px !important;
  border-radius: 50%;
  position: absolute;
  background-color: var(--color-bg-primary);
  border: 1px solid var(--color-shape-secondary);
  top: -8px;
  left: -8px;
  background-size: 10px;
  transition: all 0.15s cubic-bezier(0.22, 1, 0.36, 1);
  opacity: 0;
}
.notifications .notification .content {
  display: none;
}
.notifications .notification .content .title {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
  font-weight: 600;
  margin: 0px 0px 2px 0px;
}
.notifications .notification .content .label {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
}
.notifications .notification .content .buttons {
  display: flex;
  flex-direction: row;
  gap: 0px 8px;
  margin: 12px 0px 0px 0px;
}
.notifications .notification .content .buttons:empty {
  display: none;
}
.notifications .notification .content .button {
  font-size: var(--font-size-small);
  line-height: var(--line-height-small);
  letter-spacing: var(--letter-spacing-small);
  font-weight: 500;
}
.notifications .notification .content .element {
  display: inline;
}
.notifications .notification .content .element .iconObject {
  display: inline;
  margin-right: 4px;
}
.notifications .notification .content .element .iconObject:empty {
  display: none;
}
.notifications .notification .content .element .name {
  display: inline;
  font-weight: 500;
}
.notifications .notification:first-child .content {
  display: block;
}
.notifications .notification:first-child:hover .icon.notificationDelete {
  opacity: 1;
}

.notifications.isExpanded .head {
  display: flex;
}
.notifications.isExpanded .notification .content {
  display: block;
}
.notifications.isExpanded .notification:hover .icon.notificationDelete {
  opacity: 1;
}

